# Generates the console-tab and Trip Card artboards with one shared shell and token set.
FR = "'Fraunces', Georgia, serif"
MO = "'Geist Mono', ui-monospace, SFMono-Regular, Menlo, monospace"
T = dict(ground="#FAFAF8", card="#FFFFFF", border="#E7E4DD", chip="#F6F5F1", navy="#1E3A5F", ink="#1F2733",
         muted="#6A7480", faint="#B0AAA0", teal="#2E8B8B", tealink="#226B6B", tealwash="rgba(46,139,139,0.10)",
         gold="#E8B339", goldink="#8A6414", goldwash="rgba(232,179,57,0.15)", green="#5DCAA5", greenink="#2F7D63",
         coral="#E85D55", coralbg="#FFF4F4", coralborder="#FCCACA", line="#E8E8E2")

HEAD = """<!doctype html>
<html>
<head>
  <meta charset="utf-8">
  <script src="./support.js"></script>
</head>
<body>
<x-dc>
<helmet>
  <link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&amp;family=Inter:wght@400;500;600&amp;family=Geist+Mono:wght@400;500&amp;display=swap">
  <style>
    body { margin: 0; background: #FAFAF8; color: #1F2733; font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; -webkit-font-smoothing: antialiased; }
    a { color: #1E3A5F; text-decoration: none; } a:hover { color: #E85D55; }
    * { box-sizing: border-box; }
    p { margin: 0; }
  </style>
</helmet>
"""
FOOT = """</x-dc>
</body>
</html>
"""

def svg(path, color="#1F2733", size=16, extra=""):
    return f'<svg width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" stroke="{color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"{extra}>{path}</svg>'
OP = ' style="opacity: 0.7;"'
ROT = ' style="transform: rotate(90deg);"'
ICO = dict(
    home='<path d="M3 11l9-8 9 8v10a1 1 0 0 1-1 1h-5v-6h-6v6H4a1 1 0 0 1-1-1z"/>',
    plans='<rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/>',
    ai='<rect x="3" y="8" width="18" height="12" rx="2"/><path d="M12 8V4M8 4h8M8 14h.01M16 14h.01"/>',
    discover='<circle cx="12" cy="12" r="9"/><path d="M15 9l-2 6-4 2 2-6z"/>',
    experts='<circle cx="9" cy="8" r="3.5"/><path d="M2.5 20a6.5 6.5 0 0 1 13 0M16 4a3.5 3.5 0 0 1 0 7M21.5 20a6.5 6.5 0 0 0-5-6.3"/>',
    bookings='<path d="M21 8l-9-5-9 5v8l9 5 9-5z"/><path d="M3 8l9 5 9-5M12 13v8"/>',
    inbox='<path d="M22 12h-6l-2 3h-4l-2-3H2"/><path d="M5.5 5h13L22 12v6a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2v-6z"/>',
    profile='<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',
    bell='<path d="M18 8a6 6 0 0 0-12 0c0 7-3 9-3 9h18s-3-2-3-9"/><path d="M13.7 21a2 2 0 0 1-3.4 0"/>',
    chev='<path d="M9 6l6 6-6 6"/>', arrow='<path d="M5 12h14M13 6l6 6-6 6"/>', plus='<path d="M12 5v14M5 12h14"/>',
    search='<circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/>', pin='<path d="M12 22s7-7 7-12a7 7 0 0 0-14 0c0 5 7 12 7 12z"/><circle cx="12" cy="10" r="2.5"/>',
    check='<path d="M20 6L9 17l-5-5"/>', clock='<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
    map='<path d="M1 6v16l7-4 8 4 7-4V2l-7 4-8-4z"/><path d="M8 2v16M16 6v16"/>', share='<circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="M8.6 13.5l6.8 4M15.4 6.5l-6.8 4"/>',
    chat='<path d="M21 12a8 8 0 0 1-11.6 7.1L4 20l1.1-4.4A8 8 0 1 1 21 12z"/>', card='<rect x="2" y="5" width="20" height="14" rx="2"/><path d="M2 10h20"/>',
    x='<path d="M6 6l12 12M18 6L6 18"/>', spark='<path d="M12 3l1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8z"/>',
    camera='<path d="M4 8h3l2-3h6l2 3h3v12H4z"/><circle cx="12" cy="13" r="3.5"/>',
    heart='<path d="M12 21s-7-4.6-9.3-9A5.2 5.2 0 0 1 12 6a5.2 5.2 0 0 1 9.3 6c-2.3 4.4-9.3 9-9.3 9z"/>',
    train='<rect x="5" y="3" width="14" height="14" rx="3"/><path d="M5 11h14M8 21l2-4M16 21l-2-4M9 15h.01M15 15h.01"/>',
    walk='<circle cx="13" cy="4" r="1.5"/><path d="M10 22l2-7-3-2 1-5 4 1 2 3M8 12l-1 3M14 22l-2-7"/>',
)

def sidebar(active):
    items = [("Plan", [("home","Home"),("plans","My plans"),("ai","Start with AI")]),
             ("Marketplace", [("discover","Discover"),("experts","Experts"),("bookings","Bookings")]),
             ("Inbox", [("inbox","Inbox")]), ("Account", [("profile","Profile")])]
    out = [f'<div style="width: 220px; flex-shrink: 0; display: flex; flex-direction: column; border-right: 1px solid {T["line"]}; background: {T["card"]};">',
           f'<div style="height: 52px; display: flex; align-items: center; padding: 0 16px; border-bottom: 1px solid {T["line"]}; font-family: {FR}; font-size: 18px; font-weight: 600; color: {T["navy"]};">Traveloure</div>',
           '<div style="display: flex; flex-direction: column; gap: 12px; padding: 12px 10px;">']
    for label, rows in items:
        out.append('<div style="display: flex; flex-direction: column; gap: 2px;">')
        out.append(f'<span style="font-family: {MO}; font-size: 10px; font-weight: 500; text-transform: uppercase; letter-spacing: 1.2px; color: {T["faint"]}; padding: 0 10px 4px;">{label}</span>')
        for key, name in rows:
            on = key == active
            color = T["coral"] if on else T["ink"]
            bg = "background: rgba(232,93,85,0.08); font-weight: 600;" if on else ""
            badge = f'<span style="min-width: 18px; height: 18px; padding: 0 5px; border-radius: 9px; background: {T["coral"]}; color: #FFFFFF; font-size: 10px; font-weight: 600; display: flex; align-items: center; justify-content: center;">3</span>' if key == "inbox" else ""
            out.append(f'<div style="display: flex; align-items: center; gap: 10px; height: 34px; padding: 0 10px; border-radius: 8px; font-size: 13px; color: {color}; {bg}">{svg(ICO[key], color, 16, "" if on else OP)}<span style="flex: 1;">{name}</span>{badge}</div>')
        out.append('</div>')
    out.append('</div>')
    out.append(f'<div style="margin-top: auto; display: flex; align-items: center; gap: 10px; padding: 12px 14px; border-top: 1px solid {T["line"]};"><span style="width: 34px; height: 34px; border-radius: 17px; background: linear-gradient(135deg, #E85D55, #1E3A5F); color: #FFFFFF; font-size: 13px; font-weight: 600; display: flex; align-items: center; justify-content: center;">LD</span><div style="display: flex; flex-direction: column;"><span style="font-size: 13px; font-weight: 500; color: {T["ink"]};">[Your name]</span><span style="font-size: 11px; color: {T["muted"]};">[email]</span></div></div>')
    out.append('</div>')
    return "".join(out)

def topbar():
    return (f'<div style="height: 52px; flex-shrink: 0; display: flex; align-items: center; justify-content: flex-end; gap: 14px; padding: 0 24px; background: {T["card"]}; border-bottom: 1px solid {T["line"]};">'
            f'{svg(ICO["bell"], T["muted"], 20)}<span style="width: 30px; height: 30px; border-radius: 15px; background: linear-gradient(135deg, #E85D55, #1E3A5F);"></span></div>')

def eyebrow(text, color=None):
    return f'<span style="font-family: {MO}; font-size: 10.5px; text-transform: uppercase; letter-spacing: 0.12em; color: {color or T["muted"]};">{text}</span>'

def pending(text):
    return f'<span style="font-family: {MO}; font-size: 9px; text-transform: uppercase; letter-spacing: 0.08em; padding: 2px 6px; border-radius: 4px; background: {T["coral"]}; color: #FFFFFF; white-space: nowrap;">{text}</span>'

def fixchip(text):
    return f'<span style="font-family: {MO}; font-size: 9px; text-transform: uppercase; letter-spacing: 0.08em; padding: 2px 6px; border-radius: 4px; background: {T["tealwash"]}; color: {T["tealink"]}; white-space: nowrap;">{text}</span>'

def masthead(title, sub, right="", eb="Traveler console"):
    return (f'<div style="display: flex; align-items: flex-end; justify-content: space-between; gap: 24px; padding: 26px 32px 22px; background: {T["card"]}; border-bottom: 1px solid {T["border"]};">'
            f'<div style="display: flex; flex-direction: column; gap: 6px;">{eyebrow(eb)}<h1 style="margin: 0; font-family: {FR}; font-size: 26px; font-weight: 600; color: {T["navy"]};">{title}</h1><span style="font-size: 13.5px; color: {T["muted"]};">{sub}</span></div>'
            f'<div style="display: flex; align-items: center; gap: 10px;">{right}</div></div>')

def btn(label, kind="primary", icon=None):
    if kind == "primary":
        st = f"background: {T['coral']}; color: #FFFFFF; border: 1px solid {T['coral']};"
    elif kind == "navy":
        st = f"background: {T['navy']}; color: #FFFFFF; border: 1px solid {T['navy']};"
    else:
        st = f"background: {T['card']}; color: {T['ink']}; border: 1px solid {T['border']};"
    ic = svg(ICO[icon], "#FFFFFF" if kind in ("primary","navy") else T["ink"], 14) if icon else ""
    return f'<span style="display: inline-flex; align-items: center; gap: 6px; height: 36px; padding: 0 14px; border-radius: 8px; font-size: 13px; font-weight: 600; {st}">{ic}{label}</span>'

def pill(text, tone):
    tones = dict(planning=(T["muted"], "transparent", T["border"]), checkout=("#A67A12","#E8B33926","#E8B33959"), booked=(T["greenink"],"#5DCAA526","#5DCAA559"),
                 expert=(T["tealink"],"#2E8B8B26","#2E8B8B59"), pending=("#B45309","#FDF1E5","#F6D7B6"), cancel=(T["coral"],T["coralbg"],T["coralborder"]), neutral=(T["muted"],T["chip"],T["border"]))
    fg,bg,bd = tones[tone]
    return f'<span style="display: inline-flex; align-items: center; padding: 2px 8px; border-radius: 6px; background: {bg}; border: 1px solid {bd}; font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em; color: {fg}; white-space: nowrap;">{text}</span>'

def card(inner, pad="16px", extra="", bg=None):
    return f'<div style="display: flex; flex-direction: column; gap: 10px; padding: {pad}; border: 1px solid {T["border"]}; border-radius: 12px; background: {bg or T["card"]}; {extra}">{inner}</div>'

def plan_chip(label="Adding to", plan="Your Kyoto wedding"):
    return (f'<span style="display: inline-flex; align-items: center; gap: 8px; height: 32px; padding: 0 12px; border-radius: 999px; background: {T["tealwash"]}; border: 1px solid #2E8B8B59; font-size: 12.5px; color: {T["tealink"]};">'
            f'{svg(ICO["plans"], T["tealink"], 14)}<span>{label}: <strong>{plan}</strong></span><span style="font-family: {MO}; font-size: 10px; text-transform: uppercase; letter-spacing: 0.08em;">change</span></span>')

def shell(active, body, width=1440, height=None):
    h = f" height: {height}px;" if height else ""
    return (HEAD + f'<div style="width: {width}px;{h} background: {T["ground"]}; display: flex; overflow: hidden;">' + sidebar(active)
            + f'<div style="flex: 1; min-width: 0; display: flex; flex-direction: column;">' + topbar() + body + '</div></div>' + FOOT)

def note(text):
    return f'<span style="font-size: 11.5px; line-height: 1.5; color: {T["muted"]};">{text}</span>'

def mono(text, color=None, size="11px"):
    return f'<span style="font-family: {MO}; font-size: {size}; color: {color or T["muted"]};">{text}</span>'

def h3(text, size="17px"):
    return f'<span style="font-family: {FR}; font-size: {size}; font-weight: 600; color: {T["navy"]};">{text}</span>'

def row(inner, extra=""):
    return f'<div style="display: flex; align-items: center; gap: 12px; {extra}">{inner}</div>'

def section_head(eb, title, right=""):
    return (f'<div style="display: flex; align-items: flex-end; justify-content: space-between;"><div style="display: flex; flex-direction: column; gap: 4px;">{eyebrow(eb, T["coral"])}{h3(title, "20px")}</div>{right}</div>')

# ---------- summary card (shared by Home and used as the Trip Card's Stage A) ----------
def summary_card():
    hero = (f'<div style="display: flex; flex-direction: column; gap: 10px; padding: 18px 18px 16px; border-radius: 12px 12px 0 0; background: {T["navy"]}; color: #FFFFFF;">'
            f'<div style="display: flex; align-items: center; justify-content: space-between;"><div style="display: flex; gap: 6px;">{pill("3 days away","checkout")}{pill("Final · v2","booked")}</div>{mono("TRV-000123", "#C9D3E0")}</div>'
            f'<span style="font-family: {FR}; font-size: 22px; font-weight: 600;">Your Kyoto wedding</span>'
            f'<span style="font-size: 12.5px; color: #C9D3E0;">Oct 2 – Oct 4, 2026 · Kyoto · 2 traveling · 24 invited</span>'
            f'<div style="display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 6px; padding-top: 6px; border-top: 1px solid rgba(255,255,255,0.14);">'
            + "".join(f'<div style="display: flex; flex-direction: column; gap: 1px;"><span style="font-family: {FR}; font-size: 18px; font-weight: 600;">{v}</span><span style="font-family: {MO}; font-size: 9.5px; text-transform: uppercase; letter-spacing: 0.08em; color: #C9D3E0;">{l}</span></div>' for v,l in [("3","Days"),("9","Activities"),("4","Legs"),("1h 40","Transit")])
            + '</div></div>')
    body = (f'<div style="display: flex; flex-direction: column; gap: 10px; padding: 12px 16px 14px;">'
            f'<div style="display: flex; align-items: center; gap: 8px; padding: 8px 10px; border-radius: 8px; background: {T["coralbg"]}; border: 1px solid {T["coralborder"]};">{svg(ICO["spark"], T["coral"], 14)}<span style="flex: 1; font-size: 12.5px; color: {T["ink"]};">2 items are with Mika, awaiting her update</span>{mono("Today&#39;s move", T["coral"], "9.5px")}</div>'
            f'<div style="display: flex; gap: 6px; flex-wrap: wrap;">{pill("6 planning","planning")}{pill("1 in checkout","checkout")}{pill("2 booked","booked")}{pill("with Mika","expert")}</div>'
            f'<div style="display: flex; gap: 8px;">{btn("View Trip Card","navy")}{btn("Message Mika","outline","chat")}</div></div>')
    return f'<div style="border: 1px solid {T["border"]}; border-radius: 12px; background: {T["card"]}; overflow: hidden; width: 520px;">{hero}{body}</div>'

# ---------- HOME ----------
def home():
    left = []
    left.append(f'<div style="display: flex; flex-direction: column; gap: 4px;"><h1 style="margin: 0; font-family: {FR}; font-size: 26px; font-weight: 600; color: {T["navy"]};">Welcome back</h1><span style="font-size: 13.5px; color: {T["muted"]};">2 active plans · 1 thing to do today</span></div>')
    left.append(card(f'<div style="display: flex; align-items: center; justify-content: space-between;">{eyebrow("While you were away")}<a href="#" style="font-family: {MO}; font-size: 10.5px; color: {T["tealink"]};">All updates</a></div>'
        f'<div style="display: flex; flex-direction: column; gap: 7px; font-size: 13px; color: {T["ink"]};">'
        f'<span>Mika added an Expert Note to the ceremony item</span><span>Your kimono fitting is ready for checkout</span><span>3 days until Kyoto. Your Trip Card is ready.</span></div>'
        + note("Every line is a diary row or a real notification. Nothing here is invented.")))
    left.append(f'<div style="display: flex; flex-direction: column; gap: 10px;"><div style="display: flex; align-items: center; justify-content: space-between;">{h3("Your active plans")}<a href="#" style="font-family: {MO}; font-size: 10.5px; color: {T["tealink"]};">All plans</a></div>'
        f'<div style="display: flex; gap: 8px;"><span style="display: inline-flex; align-items: center; gap: 8px; padding: 8px 12px; border-radius: 10px; border: 1px solid {T["coral"]}; background: rgba(232,93,85,0.06); font-size: 12.5px; font-weight: 600; color: {T["ink"]};">Your Kyoto wedding {mono("3 days", T["coral"], "10px")}</span><span style="display: inline-flex; align-items: center; gap: 8px; padding: 8px 12px; border-radius: 10px; border: 1px solid {T["border"]}; font-size: 12.5px; color: {T["ink"]};">Lisbon long weekend {mono("planning", None, "10px")}</span></div>'
        + summary_card() + '</div>')
    left.append(f'<div style="display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; width: 520px;">'
        + card(f'<div style="display: flex; align-items: center; gap: 8px;">{svg(ICO["plus"], T["navy"], 16)}{h3("New plan", "15px")}</div><span style="font-size: 12px; color: {T["muted"]};">Trip, wedding, event. Opens the planner.</span>{fixchip("one door · D11")}', "14px", "", T["chip"])
        + card(f'<div style="display: flex; align-items: center; gap: 8px;">{svg(ICO["ai"], T["navy"], 16)}{h3("Start with AI", "15px")}</div><span style="font-size: 12px; color: {T["muted"]};">Describe it in a sentence. The planner fills in.</span>{fixchip("same modal")}', "14px", "", T["chip"]) + '</div>')
    left.append(card(f'<div style="display: flex; align-items: center; justify-content: space-between;">{eyebrow("Saved for later")}{mono("1")}</div>'
        f'<div style="display: flex; align-items: center; justify-content: space-between;"><div style="display: flex; flex-direction: column; gap: 2px;"><span style="font-size: 14px; font-weight: 500;">Porto, 3 nights</span><span style="font-size: 12px; color: {T["muted"]};">Nov 6 – Nov 9 · 2 travelers</span></div><div style="display: flex; align-items: center; gap: 10px;">{pill("12 days left","pending")}{btn("Continue","outline")}</div></div>'
        + note("Hidden when empty. Shown only for a saved draft with an expiry.")))
    rail = []
    rail.append(card(f'<div style="display: flex; align-items: center; justify-content: space-between;">{eyebrow("TravelPulse", T["tealink"])}{fixchip("restyled")}</div>'
        f'<div style="display: flex; flex-direction: column; gap: 8px; font-size: 12px;">'
        + "".join(f'<div style="display: flex; align-items: center; justify-content: space-between;"><span>{c}</span>{mono(t, T["greenink"] if "+" in t else T["muted"], "10.5px")}</div>' for c,t in [("Kyoto","+18% this month"),("Lisbon","+9%"),("Porto","steady")])
        + '</div>' + note("Reads the real trending endpoint. Empty state says so; no fallback list.")))
    rail.append(card(f'{eyebrow("Your experts")}'
        f'<div style="display: flex; align-items: center; gap: 10px;"><span style="width: 30px; height: 30px; border-radius: 15px; background: linear-gradient(135deg, #E85D55, #1E3A5F); color: #FFFFFF; font-size: 11px; font-weight: 600; display: flex; align-items: center; justify-content: center;">MT</span><div style="display: flex; flex-direction: column;"><span style="font-size: 13px; font-weight: 500;">Mika Tanaka</span><span style="font-size: 11px; color: {T["muted"]};">Your Kyoto wedding · assigned</span></div></div>'
        f'{btn("Message Mika","outline","chat")}{fixchip("fix: listed AI chats before")}'))
    rail.append(card(f'{eyebrow("Action items")}<div style="display: flex; flex-direction: column; gap: 6px; font-size: 12px;"><div style="display: flex; gap: 8px; align-items: flex-start;"><span style="margin-top: 5px; width: 6px; height: 6px; border-radius: 3px; background: {T["gold"]}; flex-shrink: 0;"></span><span>Kimono fitting: payment pending</span></div></div>'))
    rail.append(card(f'{eyebrow("Recommended for your plans")}<div style="display: flex; flex-direction: column; gap: 8px; font-size: 12px;"><div style="display: flex; align-items: center; justify-content: space-between;"><div style="display: flex; flex-direction: column;"><span style="font-weight: 500;">Kimono fitting · Gion</span><span style="font-size: 11px; color: {T["muted"]};">from $85 · 4.9</span></div>{btn("Add to plan","outline")}</div></div>{fixchip("fix: Add to cart was inert")}'))
    body = (f'<div style="display: flex; gap: 24px; padding: 28px 32px;"><div style="flex: 1; display: flex; flex-direction: column; gap: 18px;">' + "".join(left) + '</div>'
            f'<div style="width: 280px; flex-shrink: 0; display: flex; flex-direction: column; gap: 12px;">' + "".join(rail) + '</div></div>')
    return shell("home", body, height=1120)

# ---------- MY PLANS ----------
def myplans():
    def trip_row(title, meta, chips, status, primary, thumb_bg):
        return (f'<div style="display: flex; align-items: center; gap: 16px; padding: 14px 16px; border: 1px solid {T["border"]}; border-radius: 12px; background: {T["card"]};">'
                f'<span style="width: 64px; height: 64px; border-radius: 10px; background: {thumb_bg}; flex-shrink: 0;"></span>'
                f'<div style="flex: 1; display: flex; flex-direction: column; gap: 5px;"><div style="display: flex; align-items: center; gap: 8px;">{h3(title, "16px")}{chips}</div><span style="font-size: 12.5px; color: {T["muted"]};">{meta}</span></div>'
                f'<div style="display: flex; align-items: center; gap: 12px;">{status}{primary}</div></div>')
    occ = lambda t: f'<span style="padding: 2px 7px; border-radius: 5px; background: {T["goldwash"]}; font-family: {MO}; font-size: 9.5px; color: {T["goldink"]};">{t}</span>'
    ref = lambda t: mono(t, None, "10px")
    sections = []
    sections.append(f'<div style="display: flex; flex-direction: column; gap: 10px;">{section_head("Traveling now · 0", "Nothing underway")}{note("Section renders only with a plan whose dates contain today.")}</div>')
    sections.append(f'<div style="display: flex; flex-direction: column; gap: 10px;">{section_head("Final · 1", "Ready to travel")}'
        + trip_row("Your Kyoto wedding", "Oct 2 – Oct 4, 2026 · Kyoto · 2 traveling · 24 invited", occ("wedding")+ref("TRV-000123")+pill("Final · v2","booked"), pill("3 days away","checkout"), btn("View Trip Card","navy"), "linear-gradient(135deg, #1E3A5F, #2E8B8B)") + '</div>'
        + f'<div style="display: flex; flex-direction: column; gap: 10px;">{section_head("In planning · 1", "Plans you are building")}'
        + trip_row("Lisbon long weekend", "Nov 14 – Nov 17, 2026 · Lisbon · 2 traveling", ref("TRV-000131"), pill("planning","planning"), btn("Open slip","outline"), "linear-gradient(135deg, #E8B339, #E85D55)") + '</div>')
    showall = '<a href="#" style="font-family: ' + MO + '; font-size: 10.5px; color: ' + T["tealink"] + ';">Show all 4</a>'
    sections.append(f'<div style="display: flex; flex-direction: column; gap: 10px;">{section_head("Past · 4", "Where you have been", showall)}'
        + trip_row("Porto, 3 nights", "Mar 8 – Mar 11, 2026 · Porto", ref("TRV-000087")+pill("Final · v1","booked"), pill("completed","neutral"), btn("View Trip Card","outline"), "linear-gradient(135deg, #6A7480, #B0AAA0)")
        + fixchip("fix: Show all had no handler; list capped at 3") + '</div>')
    filters = (f'<div style="display: flex; align-items: center; gap: 10px;"><div style="display: flex; align-items: center; gap: 8px; height: 36px; padding: 0 12px; width: 280px; border: 1px solid {T["border"]}; border-radius: 8px; background: {T["card"]};">{svg(ICO["search"], T["faint"], 14)}<span style="font-size: 13px; color: {T["faint"]};">Search plans</span></div>'
        + "".join(f'<span style="display: inline-flex; align-items: center; gap: 6px; height: 36px; padding: 0 12px; border: 1px solid {T["border"]}; border-radius: 8px; background: {T["card"]}; font-size: 12.5px;">{f}{svg(ICO["chev"], T["faint"], 12, ROT)}</span>' for f in ["Any occasion","Any status"]) + '</div>')
    body = masthead("My plans", "Every plan lives on its slip until it is final, then on its Trip Card.", btn("New plan","primary","plus")) + f'<div style="display: flex; flex-direction: column; gap: 22px; padding: 24px 32px;">{filters}' + "".join(sections) + '</div>'
    return shell("plans", body, height=960)

# ---------- START WITH AI ----------
def startai():
    convs = card(f'<div style="display: flex; align-items: center; justify-content: space-between;">{eyebrow("Conversations")}{btn("New","outline","plus")}</div>'
        f'<div style="display: flex; flex-direction: column; gap: 4px;">'
        f'<div style="display: flex; flex-direction: column; gap: 2px; padding: 10px; border-radius: 8px; background: {T["tealwash"]}; border: 1px solid #2E8B8B59;"><span style="font-size: 13px; font-weight: 500;">Rainy week in Kyoto</span><span style="font-family: {MO}; font-size: 10px; color: {T["tealink"]};">not yet a plan</span></div>'
        f'<div style="display: flex; flex-direction: column; gap: 2px; padding: 10px; border-radius: 8px;"><span style="font-size: 13px; font-weight: 500;">Wedding weekend ideas</span><span style="font-family: {MO}; font-size: 10px; color: {T["muted"]};">bound to Your Kyoto wedding · opens its slip</span></div>'
        '</div>' + note("A conversation with a plan opens that plan's drawer. This page never edits an existing plan.") + pending("ruling 1"))
    thread = (f'<div style="flex: 1; display: flex; flex-direction: column; border: 1px solid {T["border"]}; border-radius: 12px; background: {T["card"]}; overflow: hidden;">'
        f'<div style="display: flex; flex-direction: column; gap: 12px; padding: 18px; flex: 1; background: {T["ground"]};">'
        f'<div style="align-self: flex-end; max-width: 380px; padding: 10px 13px; border-radius: 12px 12px 3px 12px; background: {T["navy"]}; color: #FFFFFF; font-size: 13px; line-height: 1.5;">We land in Kyoto on the 2nd for our wedding on the 3rd, staying through the 4th. Two of us, about 24 guests.</div>'
        f'<div style="align-self: flex-start; max-width: 420px; padding: 10px 13px; border-radius: 12px 12px 12px 3px; background: {T["card"]}; border: 1px solid {T["border"]}; font-size: 13px; line-height: 1.5;">Got it: Kyoto, Oct 2 to 4, two traveling, a wedding with guests. The draft on the right is filled from what you said and nothing more. Want to tell me the ceremony time, or shall we open the planner?</div>'
        '</div>'
        f'<div style="display: flex; align-items: center; gap: 8px; height: 48px; padding: 0 14px; border-top: 1px solid {T["border"]};"><span style="flex: 1; font-size: 13px; color: {T["faint"]};">Tell me what you are planning…</span>{svg(ICO["arrow"], T["navy"], 18)}</div></div>')
    draft = card(f'<div style="display: flex; align-items: center; gap: 8px;">{svg(ICO["spark"], T["tealink"], 14)}{eyebrow("Plan draft")}</div>'
        + note("Fills in as you chat. Nothing here is guessed.")
        + "".join(f'<div style="display: flex; flex-direction: column; gap: 2px; padding: 8px 0; border-top: 1px solid {T["chip"]};"><span style="font-family: {MO}; font-size: 10px; text-transform: uppercase; letter-spacing: 0.08em; color: {T["muted"]};">{k}</span><span style="font-size: 13.5px; color: {T["ink"] if v != "Not discussed yet" else T["faint"]}; font-style: {"normal" if v != "Not discussed yet" else "italic"};">{v}</span></div>' for k,v in [("Destination","Kyoto"),("Dates","Oct 2 – Oct 4, 2026"),("Traveling","2"),("Occasion","Wedding · 24 guests"),("Events","Not discussed yet")])
        + btn("Continue in the planner","primary","arrow") + note("Opens the one planning modal with these filled in. The plan is minted there, on the same steps every door uses.") + fixchip("fix: minted directly before · D11, D13"))
    body = masthead("Start with AI", "Describe the trip. The draft fills in from what you actually said.", "", "Door") + f'<div style="display: flex; gap: 16px; padding: 24px 32px; height: 640px;"><div style="width: 260px; flex-shrink: 0;">{convs}</div>{thread}<div style="width: 300px; flex-shrink: 0;">{draft}</div></div>'
    return shell("ai", body, height=830)

# ---------- DISCOVER ----------
def discover():
    railtab = lambda t, on=False: f'<span style="padding: 7px 12px; border-radius: 8px; font-size: 12.5px; {"background: "+T["navy"]+"; color: #FFFFFF;" if on else "border: 1px solid "+T["border"]+"; color: "+T["ink"]+";"}">{t}</span>'
    right = f'<div style="display: flex; gap: 6px;">{railtab("Destinations", True)}{railtab("Ready-made")}{railtab("Events")}{railtab("Services")}</div>'
    def city(name, sub, grad):
        return (f'<div style="display: flex; flex-direction: column; border: 1px solid {T["border"]}; border-radius: 14px; background: {T["card"]}; overflow: hidden;"><span style="height: 120px; background: {grad};"></span>'
                f'<div style="display: flex; flex-direction: column; gap: 6px; padding: 12px 14px 14px;"><div style="display: flex; align-items: center; justify-content: space-between;">{h3(name, "16px")}{mono(sub, None, "10px")}</div>'
                f'<div style="display: flex; gap: 8px;">{btn("Plan now","navy")}{btn("Add to plan","outline")}</div></div></div>')
    grid = f'<div style="display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px;">' + city("Kyoto","41 experts","linear-gradient(135deg, #1E3A5F, #2E8B8B)") + city("Lisbon","23 experts","linear-gradient(135deg, #E8B339, #E85D55)") + city("Porto","12 experts","linear-gradient(135deg, #2E8B8B, #5DCAA5)") + city("Tokyo","38 experts","linear-gradient(135deg, #1F2733, #6A7480)") + '</div>'
    search = (f'<div style="display: flex; align-items: center; gap: 10px;"><div style="display: flex; align-items: center; gap: 8px; height: 40px; padding: 0 14px; flex: 1; border: 1px solid {T["border"]}; border-radius: 10px; background: {T["card"]};">{svg(ICO["search"], T["faint"], 14)}<span style="font-size: 13px; color: {T["faint"]};">What do you need help with?</span></div>'
        f'<div style="display: flex; align-items: center; gap: 8px; height: 40px; padding: 0 14px; width: 260px; border: 1px solid {T["border"]}; border-radius: 10px; background: {T["card"]};">{svg(ICO["pin"], T["faint"], 14)}<span style="font-size: 13px; color: {T["faint"]};">Where are you going?</span></div></div>')
    body = masthead("Discover", "Explore destinations and trending cities.", right, "Marketplace") + (
        f'<div style="display: flex; flex-direction: column; gap: 18px; padding: 24px 32px;">'
        f'<div style="display: flex; align-items: center; justify-content: space-between;">{plan_chip()}{fixchip("fix: renders inside the console shell now")}</div>{search}'
        f'<div style="display: flex; align-items: center; justify-content: space-between;">{section_head("Cities · 8 markets", "Plan the trip a local would take")}{mono("sorted by your plans")}</div>{grid}'
        + note("Plan now opens the planner with the city pre-filled (D14). Add to plan lands on the chip's plan through the one item rail; with no plan, the chip reads &quot;No plan yet · start one&quot; and Add opens the planner instead.") + '</div>')
    return shell("discover", body, height=880)

# ---------- EXPERTS ----------
def experts():
    def ex(initials, name, role, loc, price, grad):
        return (f'<div style="display: flex; flex-direction: column; gap: 10px; padding: 14px; border: 1px solid {T["border"]}; border-radius: 14px; background: {T["card"]};">'
                f'<div style="display: flex; align-items: center; gap: 10px;"><span style="width: 48px; height: 48px; border-radius: 24px; background: {grad}; color: #FFFFFF; font-size: 14px; font-weight: 600; display: flex; align-items: center; justify-content: center;">{initials}</span><div style="display: flex; flex-direction: column; gap: 2px;"><span style="font-family: {MO}; font-size: 9.5px; text-transform: uppercase; letter-spacing: 0.08em; color: {T["muted"]};">{role}</span>{h3(name, "15px")}<div style="display: flex; align-items: center; gap: 4px; font-size: 11.5px; color: {T["muted"]};">{svg(ICO["pin"], T["muted"], 12)}{loc}</div></div></div>'
                f'<div style="display: flex; align-items: center; justify-content: space-between;">{mono(price, T["ink"])}{mono("4.9 · 31 reviews", None, "10.5px")}</div>'
                f'{btn("Choose for this plan","navy")}<a href="#" style="font-size: 12px; color: {T["tealink"]};">View storefront</a></div>')
    grid = f'<div style="display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px;">' + ex("MT","Mika Tanaka","Local expert · Kyoto","Gion, Kyoto","from $120","linear-gradient(135deg, #E85D55, #1E3A5F)") + ex("RS","Ren Sato","Wedding planner","Kyoto","from $480","linear-gradient(135deg, #2E8B8B, #1E3A5F)") + ex("AK","Aya Kimura","Day-of coordinator","Kyoto","from $260","linear-gradient(135deg, #E8B339, #E85D55)") + ex("HN","Haruto Nakamura","Local expert · Kyoto","Arashiyama","from $95","linear-gradient(135deg, #1F2733, #2E8B8B)") + '</div>'
    filters = (f'<div style="display: flex; align-items: center; gap: 10px; padding: 12px; border: 1px solid {T["border"]}; border-radius: 12px; background: {T["card"]};"><div style="display: flex; align-items: center; gap: 8px; height: 36px; padding: 0 12px; flex: 1; border: 1px solid {T["border"]}; border-radius: 8px;">{svg(ICO["search"], T["faint"], 14)}<span style="font-size: 13px; color: {T["faint"]};">What do you need help with?</span></div>'
        + "".join(f'<span style="display: inline-flex; align-items: center; gap: 6px; height: 36px; padding: 0 12px; border: 1px solid {T["border"]}; border-radius: 8px; font-size: 12.5px;">{f}{svg(ICO["chev"], T["faint"], 12, ROT)}</span>' for f in ["Kyoto","Wedding","Any language"]) + f'{mono("12 found")}</div>')
    body = masthead("Experts", "Someone who already knows the way.", plan_chip("Hiring for"), "Marketplace") + (
        f'<div style="display: flex; flex-direction: column; gap: 18px; padding: 24px 32px;">{filters}'
        f'<div style="display: flex; align-items: center; justify-content: space-between;">{section_head("Local experts · 12", "Someone who already knows the way")}{mono("recommended")}</div>{grid}'
        f'<div style="display: flex; gap: 12px;">{note("Choose for this plan opens the one expert picker for the chip&#39;s plan (D6, D7). No plan yet: the button reads &quot;Start a plan to hire&quot; and opens the planner, because no expert touchpoint exists without a slip (Decision 32).")}{fixchip("fix: inside the shell · one picker")}</div></div>')
    return shell("experts", body, height=900)

# ---------- BOOKINGS ----------
def bookings():
    tabs = "".join(f'<span style="padding: 9px 2px; margin-right: 18px; border-bottom: 2px solid {T["navy"] if on else "transparent"}; font-size: 13px; font-weight: {600 if on else 400}; color: {T["navy"] if on else T["muted"]};">{t}</span>' for t,on in [("All · 5",True),("Pending · 1",False),("Active · 3",False),("Completed · 1",False),("Trips · 1",False)])
    def brow(name, provider, when, amount, status, actions):
        return (f'<div style="display: flex; align-items: center; gap: 16px; padding: 14px 16px; border-top: 1px solid {T["chip"]};">'
                f'<div style="flex: 1; display: flex; flex-direction: column; gap: 4px;"><div style="display: flex; align-items: center; gap: 8px;"><span style="font-size: 14px; font-weight: 500;">{name}</span>{status}</div><span style="font-size: 12px; color: {T["muted"]};">{provider} · {when}</span></div>'
                f'<span style="font-family: {FR}; font-size: 16px; font-weight: 600; color: {T["navy"]};">{amount}</span><div style="display: flex; gap: 8px;">{actions}</div></div>')
    group = lambda title, meta, rows: (f'<div style="border: 1px solid {T["border"]}; border-radius: 12px; background: {T["card"]}; overflow: hidden;"><div style="display: flex; align-items: center; justify-content: space-between; padding: 12px 16px; background: {T["chip"]};"><div style="display: flex; align-items: center; gap: 10px;">{h3(title, "15px")}{mono(meta, None, "10.5px")}</div><a href="#" style="font-family: {MO}; font-size: 10.5px; color: {T["tealink"]};">Open plan</a></div>{rows}</div>')
    g1 = group("Your Kyoto wedding", "3 bookings · TRV-000123",
        brow("Shinto ceremony · Shimogamo Shrine", "Booked through Mika Tanaka", "Oct 3 · 15:00", "$640", pill("confirmed","booked"), btn("Contract","outline")+btn("Message","outline","chat"))
        + brow("Reception dinner · private room", "Kiyamachi Sato", "Oct 3 · 18:30", "$1,200 deposit", pill("deposit paid","checkout"), f'<span style="display: inline-flex; align-items: center; gap: 6px; font-size: 12px; color: {T["muted"]};">Balance $2,400 due Sep 30 · {fixchip("pay on the slip · D9")}</span>')
        + brow("Kimono fitting · Gion", "Hanayome Studio", "Oct 2 · 11:00", "$170", pill("payment pending","pending"), btn("Complete payment","primary")))
    g2 = group("Porto, 3 nights", "1 booking · TRV-000087",
        brow("Douro tasting walk", "Ana Ferreira", "Mar 9", "$95", pill("completed","neutral"), btn("Review","outline")+btn("Receipt","outline")))
    body = masthead("Bookings", "Every purchase across your plans. Money after the sale lives here.", "", "Ledger") + (
        f'<div style="display: flex; flex-direction: column; gap: 18px; padding: 0 32px 24px;"><div style="display: flex; border-bottom: 1px solid {T["border"]};">{tabs}</div>{g1}{g2}'
        f'<div style="display: flex; gap: 12px;">{note("Rows are grouped by plan and name the service and the provider. A balance is paid on the plan&#39;s slip where the payer predicate decides who may (D9); this ledger only says it is due. Confirmation codes appear only once a provider issues one.")}{fixchip("fix: rows showed no service or provider name")}</div></div>')
    return shell("bookings", body, height=820)

# ---------- INBOX ----------
def inbox():
    tabs = "".join(f'<span style="display: inline-flex; align-items: center; gap: 6px; padding: 9px 2px; margin-right: 18px; border-bottom: 2px solid {T["navy"] if on else "transparent"}; font-size: 13px; font-weight: {600 if on else 400}; color: {T["navy"] if on else T["muted"]};">{t}<span style="min-width: 16px; height: 16px; padding: 0 5px; border-radius: 8px; background: {T["coral"] if on else T["chip"]}; color: {"#FFFFFF" if on else T["muted"]}; font-size: 10px; font-weight: 600; display: inline-flex; align-items: center; justify-content: center;">{n}</span></span>' for t,n,on in [("Messages","2",True),("Updates","1",False)])
    ctx = lambda kind, what: f'<span style="display: inline-flex; align-items: center; gap: 5px; padding: 2px 8px; border-radius: 999px; background: {T["chip"]}; font-family: {MO}; font-size: 10px; color: {T["muted"]};"><span style="text-transform: uppercase; letter-spacing: 0.06em;">{kind}</span>· {what}</span>'
    def trow(initials, name, ctxchip, last, when, unread, grad):
        ub = ('<span style="min-width: 18px; height: 18px; padding: 0 5px; border-radius: 9px; background: ' + T["coral"] + '; color: #FFFFFF; font-size: 10px; font-weight: 600; display: inline-flex; align-items: center; justify-content: center;">' + str(unread) + '</span>') if unread else ""
        return (f'<div style="display: flex; align-items: center; gap: 14px; padding: 14px 16px; border: 1px solid {T["border"]}; border-radius: 12px; background: {T["card"]};">'
                f'<span style="width: 40px; height: 40px; border-radius: 20px; background: {grad}; color: #FFFFFF; font-size: 13px; font-weight: 600; display: flex; align-items: center; justify-content: center;">{initials}</span>'
                f'<div style="flex: 1; display: flex; flex-direction: column; gap: 4px;"><div style="display: flex; align-items: center; gap: 8px;"><span style="font-size: 14px; font-weight: {600 if unread else 500};">{name}</span>{ctxchip}</div><span style="font-size: 12.5px; color: {T["muted"]};">{last}</span></div>'
                f'<div style="display: flex; flex-direction: column; align-items: flex-end; gap: 6px;">{mono(when, None, "10.5px")}{ub}</div></div>')
    rows = (trow("MT","Mika Tanaka", ctx("plan","Your Kyoto wedding"), "I moved the shrine arrival to 14:20, see the note on the ceremony item.", "10:42", 2, "linear-gradient(135deg, #E85D55, #1E3A5F)")
            + trow("HS","Hanayome Studio", ctx("booking","Kimono fitting · Oct 2"), "We can hold 11:00, payment closes the slot.", "Yesterday", 0, "linear-gradient(135deg, #E8B339, #E85D55)")
            + trow("RS","Ren Sato", ctx("storefront","ren-sato"), "Happy to talk through a day-of plan when you are ready.", "Sep 3", 0, "linear-gradient(135deg, #2E8B8B, #1E3A5F)"))
    upd = (f'<div style="display: flex; align-items: center; gap: 14px; padding: 14px 16px; border: 1px solid #2E8B8B59; border-radius: 12px; background: {T["tealwash"]};">{svg(ICO["bell"], T["tealink"], 18)}<div style="flex: 1; display: flex; flex-direction: column; gap: 3px;"><span style="font-size: 13.5px; font-weight: 600;">Your kimono fitting is ready for checkout</span><span style="font-size: 12px; color: {T["muted"]};">Your Kyoto wedding · 2 hours ago</span></div>{btn("Open slip","outline")}</div>')
    body = masthead("Inbox", "People and updates about your plans, in one place. AI conversations live on the plan, not here.", "", "Human") + (
        f'<div style="display: flex; flex-direction: column; gap: 14px; padding: 0 32px 24px; max-width: 860px;"><div style="display: flex; border-bottom: 1px solid {T["border"]};">{tabs}</div>{rows}'
        f'<div style="display: flex; align-items: center; gap: 10px; padding-top: 8px;">{eyebrow("Updates · preview")}</div>{upd}'
        f'<div style="display: flex; gap: 12px;">{note("Every thread carries what it is about: a plan, a booking, a listing or a storefront. Those are the four context kinds the start rail records (Decision 40, D22), read from the server, never guessed. Older threads with no context show none.")}{fixchip("enhance: context chip per thread")}</div></div>')
    return shell("inbox", body, height=760)

# ---------- PROFILE ----------
def profile():
    field = lambda k, v, hint="", faint=False: (f'<div style="display: flex; flex-direction: column; gap: 4px;"><span style="font-family: {MO}; font-size: 10px; text-transform: uppercase; letter-spacing: 0.08em; color: {T["muted"]};">{k}</span><div style="display: flex; align-items: center; height: 38px; padding: 0 12px; border: 1px solid {T["border"]}; border-radius: 8px; background: {T["chip"] if faint else T["card"]}; font-size: 13px; color: {T["faint"] if faint else T["ink"]};">{v}</div>' + (note(hint) if hint else "") + '</div>')
    photo = card(f'{eyebrow("Profile photo")}<div style="display: flex; align-items: center; gap: 16px;"><span style="width: 72px; height: 72px; border-radius: 36px; background: linear-gradient(135deg, #E85D55, #1E3A5F); color: #FFFFFF; font-size: 22px; font-weight: 600; display: flex; align-items: center; justify-content: center;">LD</span><div style="display: flex; gap: 8px;">{btn("Upload photo","outline","camera")}{btn("Remove","outline")}</div></div>')
    personal = card(f'{eyebrow("Personal information")}<div style="display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px;">{field("First name","[First]")}{field("Last name","[Last]")}</div>{field("Email","[email]","The email your account signs in with. It cannot be changed here.", True)}{field("Home city","Kyoto","We can only plan from the markets we operate in. Leave it unset if yours is not here; we will not guess one.")}')
    pay = card(f'<div style="display: flex; align-items: center; justify-content: space-between;">{eyebrow("Payment methods")}{mono("held by Stripe, never here", None, "10px")}</div>'
        f'<div style="display: flex; align-items: center; justify-content: space-between; padding: 10px 12px; border: 1px solid {T["border"]}; border-radius: 8px;"><div style="display: flex; align-items: center; gap: 10px;">{svg(ICO["card"], T["navy"], 18)}<span style="font-size: 13px;">Visa · ending 4242</span></div>{mono("default")}</div>{btn("Add a card","outline","plus")}' + note("Nothing is asked at signup. A card is saved at first purchase or here (Decision 43)."))
    prefs = card(f'{eyebrow("Travel preferences")}<div style="display: flex; flex-direction: column; gap: 6px;"><span style="font-size: 12px; color: {T["muted"]};">Travel style</span><div style="display: flex; gap: 6px; flex-wrap: wrap;">' + "".join(f'<span style="padding: 6px 11px; border-radius: 999px; border: 1px solid {T["navy"] if on else T["border"]}; background: {T["navy"] if on else T["card"]}; color: {"#FFFFFF" if on else T["ink"]}; font-size: 12px;">{t}</span>' for t,on in [("Culture",True),("Food",True),("Nature",False),("Nightlife",False),("Relaxation",False)]) + '</div></div>'
        f'<div style="display: flex; flex-direction: column; gap: 6px;"><span style="font-size: 12px; color: {T["muted"]};">Budget</span><div style="display: flex; gap: 6px;">' + "".join(f'<span style="padding: 6px 11px; border-radius: 999px; border: 1px solid {T["navy"] if on else T["border"]}; background: {T["navy"] if on else T["card"]}; color: {"#FFFFFF" if on else T["ink"]}; font-size: 12px;">{t}</span>' for t,on in [("Budget-friendly",False),("Moderate",True),("Luxury",False)]) + '</div></div>')
    occ = card(f'<div style="display: flex; align-items: center; justify-content: space-between;">{eyebrow("Occasions")}{pending("hidden until PLUS_SALES_ENABLED")}</div><span style="font-size: 13px; line-height: 1.5;">Birthdays, anniversaries, date nights in your home city. A plan arrives 14 days before each one.</span>' + note("Plus does not go on sale until a draft delivers end to end (Decision 26). Until then this card is not rendered."))
    body = masthead("Profile", "Who you are, where you live, how you pay.", btn("Save changes","primary")) + (
        f'<div style="display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; padding: 24px 32px; max-width: 980px;"><div style="display: flex; flex-direction: column; gap: 16px;">{photo}{personal}</div><div style="display: flex; flex-direction: column; gap: 16px;">{pay}{prefs}{occ}</div></div>')
    return shell("profile", body, height=900)

# ---------- TRIP CARD (desktop, post-final) ----------
def tripcard():
    hero = (f'<div style="display: flex; flex-direction: column; gap: 12px; padding: 24px 28px 20px; border-radius: 14px; background: {T["navy"]}; color: #FFFFFF;">'
            f'<div style="display: flex; align-items: center; justify-content: space-between;"><div style="display: flex; gap: 6px;">{pill("3 days away","checkout")}{pill("Final · v2","booked")}</div><div style="display: flex; gap: 8px;">{btn("Share","outline","share")}{btn("Calendar","outline")}{btn("PDF","outline")}</div></div>'
            f'<span style="font-family: {FR}; font-size: 30px; font-weight: 600;">Your Kyoto wedding</span>'
            f'<span style="font-size: 13.5px; color: #C9D3E0;">Oct 2 – Oct 4, 2026 · Kyoto · Asia/Tokyo · 2 traveling · 24 invited · with Mika Tanaka</span>'
            f'<div style="display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; padding-top: 10px; border-top: 1px solid rgba(255,255,255,0.14);">'
            + "".join(f'<div style="display: flex; flex-direction: column; gap: 1px;"><span style="font-family: {FR}; font-size: 22px; font-weight: 600;">{v}</span><span style="font-family: {MO}; font-size: 10px; text-transform: uppercase; letter-spacing: 0.08em; color: #C9D3E0;">{l}</span></div>' for v,l in [("3","Days"),("9","Activities"),("4","Legs"),("1h 40","Transit")])
            + '</div>' + f'<div style="display: flex; align-items: center; gap: 8px;">{fixchip("typographic hero · no photo of nowhere")}{fixchip("same header + strip as the summary card")}</div></div>')
    days = "".join(f'<span style="padding: 7px 12px; border-radius: 8px; font-size: 12.5px; {"background: "+T["navy"]+"; color: #FFFFFF;" if on else "border: 1px solid "+T["border"]+"; color: "+T["ink"]+";"}">{d}</span>' for d,on in [("Fri · Oct 2",False),("Sat · Oct 3",True),("Sun · Oct 4",False)])
    viewbar = f'<div style="display: flex; align-items: center; justify-content: space-between;"><div style="display: flex; gap: 6px;">{days}</div><div style="display: flex; border: 1px solid {T["border"]}; border-radius: 7px; overflow: hidden; font-size: 12px;"><span style="padding: 6px 12px; background: {T["navy"]}; color: #FFFFFF;">Plan</span><span style="padding: 6px 12px; color: {T["muted"]};">Map · 7 of 9 located</span></div></div>'
    def item(time, name, sub, right, tip=None):
        t = f'<div style="display: flex; flex-direction: column; gap: 2px; padding: 6px 10px; border-left: 2px solid {T["tealink"]}; background: #F4F8F8;"><span style="font-family: {MO}; font-size: 9.5px; text-transform: uppercase; letter-spacing: 0.08em; color: {T["tealink"]};">Expert notes</span><span style="font-size: 12px;">{tip}</span></div>' if tip else ""
        return (f'<div style="display: flex; align-items: flex-start; gap: 12px; padding: 12px 16px; border-top: 1px solid {T["chip"]};"><span style="width: 44px; flex-shrink: 0; font-family: {MO}; font-size: 11.5px; color: {T["muted"]}; padding-top: 2px;">{time}</span>'
                f'<div style="flex: 1; display: flex; flex-direction: column; gap: 4px;"><span style="font-size: 14px; font-weight: 500;">{name}</span><span style="font-size: 12px; color: {T["muted"]};">{sub}</span>{t}</div><div style="display: flex; gap: 6px; align-items: center;">{right}</div></div>')
    leg = lambda a, b, mode, src: (f'<div style="display: flex; align-items: center; gap: 10px; padding: 8px 16px 8px 72px; background: {T["ground"]}; border-top: 1px solid {T["chip"]};">{svg(ICO[mode], T["muted"], 14)}<span style="font-size: 12px; color: {T["muted"]};">{a} → {b}</span>{src}</div>')
    plat = pill("Book on Traveloure","booked"); via = f'<span style="font-family: {MO}; font-size: 10px; color: {T["muted"]};">via GetTransfer</span>'
    itin = (f'<div style="border: 1px solid {T["border"]}; border-radius: 12px; background: {T["card"]}; overflow: hidden;">'
            f'<div style="display: flex; align-items: center; justify-content: space-between; padding: 12px 16px; background: {T["chip"]};"><div style="display: flex; flex-direction: column; gap: 2px;">{h3("Ceremony", "16px")}{mono("15:00 · Shimogamo Shrine · 24 attending")}</div>{mono("Saturday · Oct 3", None, "11px")}</div>'
            + item("11:00","Kimono fitting · Hanayome Studio, Gion","Payment pending · slot held until paid", pill("payment pending","pending"))
            + leg("Gion","Shimogamo","train","")
            + item("14:20","Arrive · Shimogamo Shrine","Arrival moved by Mika · was 14:40", pill("from your expert","expert"))
            + item("15:00","Shinto ceremony · Shimogamo Shrine","Confirmed · ref SG-4471 · shrine office +81 75 …", pill("booked","booked"), "Arrive 40 minutes early; the purification rite starts before the listed time.")
            + leg("Shimogamo","Kiyamachi","train", plat)
            + item("18:30","Reception dinner · Kiyamachi Sato","Deposit paid · balance $2,400 due Sep 30", pill("deposit paid","checkout"))
            + '</div>')
    collapsed = "".join(f'<div style="display: flex; align-items: center; justify-content: space-between; padding: 12px 16px; border: 1px solid {T["border"]}; border-radius: 10px; background: {T["card"]}; font-size: 13px;"><span>{t}</span>{mono(m)}</div>' for t,m in [("Note from Mika","1"),("Budget","$4,105 stated"),("Purchases","3"),("Change history","6")])
    agent = card(f'<div style="display: flex; align-items: center; justify-content: space-between;">{eyebrow("Booking agent", T["tealink"])}{pending("ruling 6 · Decision 44")}</div>'
        f'<div style="display: flex; flex-direction: column; gap: 8px;">'
        + "".join(f'<div style="display: flex; align-items: center; justify-content: space-between; padding: 8px 10px; border: 1px solid {T["border"]}; border-radius: 8px;"><div style="display: flex; flex-direction: column; gap: 1px;"><span style="font-size: 12.5px; font-weight: 500;">{n}</span><span style="font-size: 11px; color: {T["muted"]};">{s}</span></div>{p}</div>' for n,s,p in [("Airport transfer · Oct 2","Partner page read, price captured", pill("ready to buy","checkout")),("Hotel · Oct 2–4","Partner reports sold out for the 3rd", pill("unavailable","cancel"))])
        + '</div>' + note("The same drawer as the slip, in its post-final tab. Booked is said only with a confirmation in hand; prepared and booked are never collapsed.") + btn("Ask the agent","navy","chat"))
    expert = card(f'{eyebrow("Your expert")}<div style="display: flex; align-items: center; gap: 10px;"><span style="width: 32px; height: 32px; border-radius: 16px; background: linear-gradient(135deg, #E85D55, #1E3A5F); color: #FFFFFF; font-size: 12px; font-weight: 600; display: flex; align-items: center; justify-content: center;">MT</span><div style="display: flex; flex-direction: column;"><span style="font-size: 13.5px; font-weight: 600;">Mika Tanaka</span><span style="font-size: 11.5px; color: {T["muted"]};">Assigned · 1 suggestion waiting</span></div></div>{btn("Message Mika","outline","chat")}')
    sugg = card(f'{eyebrow("Suggestion from Mika")}<span style="font-size: 13px; line-height: 1.5;">Move the reception start to 18:00 so photos catch the light on Kiyamachi.</span><div style="display: flex; gap: 8px;">{btn("Accept","navy")}{btn("Decline","outline")}</div>' + note("Accepting on a final plan advances the version automatically."))
    revise = card(f'{eyebrow("Need to change the plan?")}<span style="font-size: 13px; line-height: 1.5;">Editing happens on the slip. Back to planning reopens it; the Trip Card shows &quot;Being revised&quot; until you finalize again.</span>{btn("Back to planning","outline")}' + note("Suppressed inside the 48-hour window and once underway."))
    body = (f'<div style="display: flex; gap: 24px; padding: 24px 32px;"><div style="flex: 1; display: flex; flex-direction: column; gap: 16px;">{hero}{viewbar}{itin}<div style="display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px;">{collapsed}</div>'
            f'<div style="display: flex; gap: 12px;">{note("One page, no tab shell: the dead Bookings tab is gone and purchases live in the Purchases drawer and the Bookings ledger. Map view renders located stops only, says 7 of 9, and never centres on a default coordinate.")}{fixchip("fix: tab shell · Null Island")}</div></div>'
            f'<div style="width: 320px; flex-shrink: 0; display: flex; flex-direction: column; gap: 12px;">{agent}{expert}{sugg}{revise}</div></div>')
    return shell("plans", body, height=1140)

# ---------- TRIP CARD (mobile, live day) ----------
def tripmobile():
    hero = (f'<div style="display: flex; flex-direction: column; gap: 8px; padding: 18px 18px 14px; background: {T["navy"]}; color: #FFFFFF;">'
            f'<div style="display: flex; align-items: center; justify-content: space-between;">{pill("Underway · day 2","booked")}{mono("Asia/Tokyo", "#C9D3E0", "10px")}</div>'
            f'<span style="font-family: {FR}; font-size: 22px; font-weight: 600;">Your Kyoto wedding</span><span style="font-size: 12px; color: #C9D3E0;">Saturday · Oct 3 · Ceremony day</span></div>')
    upnext = (f'<div style="display: flex; flex-direction: column; gap: 10px; margin: 14px 14px 0; padding: 14px; border-radius: 14px; background: {T["card"]}; border: 1px solid #2E8B8B59;">'
              f'<div style="display: flex; align-items: center; justify-content: space-between;">{eyebrow("Up next", T["tealink"])}{mono("in 38 min", T["tealink"], "11px")}</div>'
              f'<span style="font-family: {FR}; font-size: 18px; font-weight: 600; color: {T["navy"]};">Arrive · Shimogamo Shrine</span><span style="font-size: 12.5px; color: {T["muted"]};">14:20 · moved by Mika · by train from Gion</span>'
              f'<div style="display: flex; gap: 8px;">{btn("Navigate","navy","map")}{btn("Call the shrine","outline")}</div>'
              + note("Countdown shown because the plan carries a timezone; otherwise the time alone.") + '</div>')
    def mrow(time, name, sub, p):
        return f'<div style="display: flex; gap: 10px; padding: 12px 0; border-top: 1px solid {T["chip"]};"><span style="width: 40px; flex-shrink: 0; font-family: {MO}; font-size: 11px; color: {T["muted"]}; padding-top: 2px;">{time}</span><div style="flex: 1; display: flex; flex-direction: column; gap: 3px;"><span style="font-size: 13.5px; font-weight: 500;">{name}</span><span style="font-size: 11.5px; color: {T["muted"]};">{sub}</span></div>{p}</div>'
    today = (f'<div style="display: flex; flex-direction: column; margin: 14px; padding: 0 14px; border-radius: 14px; background: {T["card"]}; border: 1px solid {T["border"]};"><div style="display: flex; align-items: center; justify-content: space-between; padding: 12px 0 8px;">{h3("Today", "15px")}{mono("1 of 4 done")}</div>'
             + mrow("11:00","Kimono fitting","Hanayome Studio · done", pill("done","neutral")) + mrow("14:20","Arrive · Shimogamo","Up next", pill("next","expert")) + mrow("15:00","Shinto ceremony","ref SG-4471", pill("booked","booked")) + mrow("18:30","Reception dinner","Kiyamachi Sato", pill("deposit paid","checkout")) + '</div>')
    agent = f'<div style="display: flex; align-items: center; gap: 10px; margin: 0 14px; padding: 12px 14px; border-radius: 12px; background: {T["tealwash"]}; border: 1px solid #2E8B8B59;">{svg(ICO["chat"], T["tealink"], 16)}<div style="flex: 1; display: flex; flex-direction: column; gap: 1px;"><span style="font-size: 12.5px; font-weight: 600; color: {T["tealink"]};">Booking agent</span><span style="font-size: 11px; color: {T["muted"]};">1 ready to buy · 1 unavailable</span></div>{svg(ICO["chev"], T["tealink"], 14)}</div>'
    push = f'<div style="margin: 14px 14px 0; padding: 10px 12px; border-radius: 10px; border: 1px dashed {T["coral"]}; display: flex; flex-direction: column; gap: 4px;">{pending("no push channel exists")}' + note("Nothing reaches a closed app. This updates only while open; a channel is its own lane.") + '</div>'
    bar = f'<div style="margin-top: auto; display: flex; gap: 8px; padding: 12px 14px 18px; background: {T["card"]}; border-top: 1px solid {T["border"]};">{btn("Map","outline","map")}<span style="flex: 1; display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 44px; border-radius: 8px; background: {T["navy"]}; color: #FFFFFF; font-size: 13px; font-weight: 600;">{svg(ICO["chat"], "#FFFFFF", 14)}Message Mika</span>{btn("Share","outline","share")}</div>'
    return HEAD + f'<div style="width: 390px; height: 844px; background: {T["ground"]}; display: flex; flex-direction: column; overflow: hidden;">{hero}{upnext}{today}{agent}{push}{bar}</div>' + FOOT

import pathlib
for name, fn in [("StartWithAI",startai),("Experts",experts),("Bookings",bookings),("Inbox",inbox),("Profile",profile),("TripCard",tripcard),("TripCardMobile",tripmobile)]:
    pathlib.Path(f"{name}.dc.html").write_text(fn())
    print(name, len(open(f"{name}.dc.html").read()))

