PINK = "#FF385C"   # root --primary (350 100% 61%) — the traveler console is NOT console-scoped, so shadcn primary resolves to this
INTER = "'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif"

def today_banner(text):
    return f'<div style="display: flex; align-items: center; gap: 10px; padding: 8px 32px; background: #FDEFEE; border-bottom: 1px solid {T["coralborder"]}; font-family: {MO}; font-size: 10.5px; color: {T["coral"]};">{svg(ICO["clock"], T["coral"], 12)}<span>TODAY · recreated from source at f3933df · {text}</span></div>'

def issue(n):
    return f'<span style="display: inline-flex; align-items: center; justify-content: center; width: 18px; height: 18px; border-radius: 9px; background: {T["coral"]}; color: #FFFFFF; font-family: {MO}; font-size: 10px; flex-shrink: 0;">{n}</span>'

def issues_strip(items):
    return ('<div style="display: flex; flex-direction: column; gap: 6px; padding: 14px 32px 20px; border-top: 1px dashed ' + T["coralborder"] + ';">'
            + f'<span style="font-family: {MO}; font-size: 10px; text-transform: uppercase; letter-spacing: 0.1em; color: {T["coral"]};">What the redraw answers</span>'
            + '<div style="display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 6px 18px;">'
            + "".join(f'<div style="display: flex; align-items: flex-start; gap: 8px; font-size: 12px; line-height: 1.45; color: {T["ink"]};">{issue(i+1)}<span>{t}</span></div>' for i, t in enumerate(items))
            + '</div></div>')

def sidebar_today(active):
    groups = [("Plan", [("home","Home"),("plans","My Plans"),("ai","AI planner")]),
              ("Marketplace", [("discover","Discover"),("experts","Experts"),("bookings","Bookings"),("events","My events"),("cart","Trip Cart")]),
              ("Inbox", [("inbox","Inbox")]), ("Account", [("profile","Profile")])]
    ico = dict(ICO); ico["events"] = '<path d="M3 17l3-9 6 5 6-5 3 9z"/><path d="M3 20h18"/>'; ico["cart"] = '<circle cx="9" cy="20" r="1.5"/><circle cx="18" cy="20" r="1.5"/><path d="M2 3h3l2.7 12.4a2 2 0 0 0 2 1.6h8.6a2 2 0 0 0 2-1.6L22 7H6"/>'
    out = [f'<div style="width: 220px; flex-shrink: 0; display: flex; flex-direction: column; border-right: 1px solid #E8E8E2; background: #FFFFFF;">',
           f'<div style="min-height: 56px; display: flex; align-items: center; padding: 16px 20px; border-bottom: 1px solid #E8E8E2; font-family: {INTER}; font-size: 17px; font-weight: 700; color: #1A1A18;">Traveloure</div>',
           '<div style="display: flex; flex-direction: column; gap: 12px; padding: 12px 10px;">']
    for label, rows in groups:
        out.append('<div style="display: flex; flex-direction: column; gap: 2px;">')
        out.append(f'<span style="font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: 1.2px; color: #AEAEA6; padding: 0 10px 4px;">{label}</span>')
        for key, name in rows:
            on = key == active
            color = "#E85D55" if on else "#7A7A72"
            bg = "background: rgba(232,85,85,0.08); font-weight: 600;" if on else ""
            badge = '<span style="min-width: 18px; height: 18px; padding: 0 4px; border-radius: 9px; background: #E85D55; color: #FFFFFF; font-size: 10px; font-weight: 600; display: flex; align-items: center; justify-content: center;">3</span>' if key == "inbox" else ""
            out.append(f'<div style="display: flex; align-items: center; gap: 10px; height: 34px; padding: 0 10px; border-radius: 8px; font-size: 13px; color: {color}; {bg}">{svg(ico[key], color, 16, "" if on else OP)}<span style="flex: 1;">{name}</span>{badge}</div>')
        out.append('</div>')
    out.append('</div>')
    out.append('<div style="margin-top: auto; display: flex; align-items: center; gap: 10px; padding: 12px 14px; border-top: 1px solid #E8E8E2;"><span style="width: 34px; height: 34px; border-radius: 17px; background: linear-gradient(135deg, #E85D55, #1E3A5F); color: #FFFFFF; font-size: 13px; font-weight: 600; display: flex; align-items: center; justify-content: center;">LD</span><div style="display: flex; flex-direction: column;"><span style="font-size: 13px; font-weight: 500; color: #1A1A18;">[Your name]</span><span style="font-size: 11px; color: #7A7A72;">[email]</span></div></div>')
    out.append('</div>')
    return "".join(out)

def shell_today(active, body, height, banner):
    return (HEAD + f'<div style="width: 1440px; height: {height}px; background: #FAFAF8; display: flex; overflow: hidden; font-family: {INTER};">' + sidebar_today(active)
            + '<div style="flex: 1; min-width: 0; display: flex; flex-direction: column;">' + topbar() + today_banner(banner) + body + '</div></div>' + FOOT)

