    L.append('<div style="display: flex; flex-direction: column; gap: 8px;"><div style="display: flex; align-items: center; gap: 6px; font-size: 13px; color: #1A1A18;">' + svg(ICO["spark"], "#E85D55", 13) + '<span>While you were away</span></div><div style="display: flex; flex-direction: column; gap: 6px; padding: 12px 16px; border-radius: 12px; background: #FFFFFF; border: 0.5px solid #E8E8E2; font-size: 12px; color: #1A1A18;"><span>• Mika added an Expert Note to the ceremony item</span><span>• 1 new notification</span><span>• Kyoto is trending: +18% this month</span><span>• 3 days until Kyoto — your Trip Card is ready</span><a href="#" style="font-size: 11px; color: #2E8B8B;">View notifications</a></div></div>')
    L.append('<div style="display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px;"><div style="display: flex; flex-direction: column; gap: 4px; padding: 16px 12px; border-radius: 12px; background: #F3F3EE;"><span style="font-size: 18px; color: #1A1A18;">+</span><span style="font-size: 13px; color: #1A1A18;">New experience</span><span style="font-size: 11px; color: #7A7A72;">Travel, wedding, event</span></div><div style="display: flex; flex-direction: column; gap: 4px; padding: 16px 12px; border-radius: 12px; background: #F3F3EE;"><span style="font-size: 18px;">🔍</span><span style="font-size: 13px; color: #1A1A18;">Find experts</span><span style="font-size: 11px; color: #7A7A72;">In your destinations</span></div></div>')
    L.append('<div style="display: flex; flex-direction: column; gap: 8px;"><div style="display: flex; align-items: center; gap: 8px; font-size: 13px; color: #1A1A18;"><span>Saved for later</span><span style="padding: 1px 7px; border-radius: 999px; background: #F3F3EE; font-size: 11px; color: #7A7A72;">1</span></div><div style="display: flex; align-items: center; justify-content: space-between; padding: 12px 16px; border-radius: 12px; background: #FFFFFF; border: 0.5px solid #E8E8E2;"><div style="display: flex; flex-direction: column; gap: 2px;"><div style="display: flex; align-items: center; gap: 8px;"><span style="font-size: 14px; color: #1A1A18;">Barcelona</span><span style="padding: 1px 7px; border-radius: 6px; background: rgba(239,159,39,0.12); font-size: 10px; color: #EF9F27;">12d left</span></div><span style="font-size: 11px; color: #7A7A72;">6 Nov – 9 Nov 2026 · 2 travelers · est. $840</span></div><span style="display: inline-flex; align-items: center; height: 32px; padding: 0 12px; border-radius: 6px; background: #E85D55; color: #FFFFFF; font-size: 12px; font-weight: 500;">Continue this trip →</span></div></div>')
    wcard = lambda t, c: f'<div style="width: 160px; flex-shrink: 0; display: flex; flex-direction: column; border-radius: 12px; border: 0.5px solid #E8E8E2; background: #FFFFFF; overflow: hidden;"><span style="height: 80px; background: linear-gradient(135deg, #FFE3E8, #FFF1F3); display: flex; align-items: center; justify-content: center;">{svg(ICO["heart"], "#E85D55", 18)}</span><div style="display: flex; flex-direction: column; gap: 6px; padding: 8px 10px 10px;"><span style="font-size: 12px; color: #1A1A18;">{t}</span><span style="font-size: 10px; color: #7A7A72;">{c}</span><div style="display: flex; gap: 6px;">{outlinebtn("+ Trip", "24px")}{outlinebtn("→", "24px")}</div></div></div>'
