    sel = lambda t, w: f'<span style="display: inline-flex; align-items: center; justify-content: space-between; width: {w}; height: 40px; padding: 0 12px; border-radius: 10px; border: 1px solid {T["border"]}; background: {T["card"]}; font-size: 13px; color: {T["ink"]};">{t}{svg(ICO["chev"], T["faint"], 12, ROT)}</span>'
