    city = lambda n, s, g: f'<div style="display: flex; flex-direction: column; border: 1px solid {T["border"]}; border-radius: 14px; background: {T["card"]}; overflow: hidden;"><span style="height: 140px; background: {g}; display: flex; align-items: flex-end; padding: 10px 12px;"><span style="font-family: {MO}; font-size: 9px; color: rgba(255,255,255,0.8);">curated hero image</span></span><div style="display: flex; align-items: center; justify-content: space-between; padding: 12px 14px 14px;"><div style="display: flex; flex-direction: column;"><span style="font-family: {FR}; font-size: 16px; font-weight: 600; color: {T["navy"]};">{n}</span><span style="font-size: 11.5px; color: {T["muted"]};">{s}</span></div><span style="padding: 7px 12px; border-radius: 8px; background: {T["navy"]}; color: #FFFFFF; font-size: 12px; font-weight: 600;">Plan now</span></div></div>'
    grid = '<div style="display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 16px;">' + city("Kyoto","41 experts · 120 gems","linear-gradient(135deg, #1E3A5F, #2E8B8B)") + city("Lisbon","23 experts · 88 gems","linear-gradient(135deg, #E8B339, #E85D55)") + city("Porto","12 experts · 40 gems","linear-gradient(135deg, #2E8B8B, #5DCAA5)") + city("Tokyo","38 experts · 210 gems","linear-gradient(135deg, #1F2733, #6A7480)") + '</div>'
