def home_after():
    def dline(date, when, text, plan, action, tone="neutral", extra=""):
        tones = dict(neutral=(T["border"], T["card"]), due=(T["coralborder"], T["coralbg"]), live=("#2E8B8B59", "#F4F8F8"))
        bd, bg = tones[tone]
        planchip = f'<span style="padding: 2px 8px; border-radius: 999px; background: {T["chip"]}; font-family: {MO}; font-size: 10px; color: {T["muted"]}; white-space: nowrap;">{plan}</span>' if plan else ""
        return (f'<div style="display: flex; align-items: center; gap: 14px; padding: 12px 16px; border: 1px solid {bd}; border-radius: 12px; background: {bg};">'
                f'<div style="width: 64px; flex-shrink: 0; display: flex; flex-direction: column;"><span style="font-family: {FR}; font-size: 16px; font-weight: 600; color: {T["navy"]};">{date}</span><span style="font-family: {MO}; font-size: 10px; color: {T["muted"]};">{when}</span></div>'
                f'<div style="flex: 1; display: flex; flex-direction: column; gap: 3px;"><span style="font-size: 13.5px; color: {T["ink"]};">{text}</span><div style="display: flex; align-items: center; gap: 8px;">{planchip}{extra}</div></div>{action}</div>')
    lines = "".join([
        dline("Today", "Sep 29", "Kimono fitting at Hanayome Studio is unpaid. The slot is held only until the claim expires.", "Your Kyoto wedding", btn("Complete payment","primary"), "due"),
        dline("Sep 30", "tomorrow", "Reception balance of $2,400 is due to Kiyamachi Sato.", "Your Kyoto wedding", btn("Pay balance","outline"), "due", mono("service_bookings.balance_due_at", None, "9.5px")),
        dline("Sep 30", "tomorrow", "The Trip Card takes over for Kyoto: the 48-hour handover.", "Your Kyoto wedding", btn("View Trip Card","navy"), "neutral", mono("derived: start − 48h", None, "9.5px")),
        dline("Oct 2", "in 3 days", "Kyoto begins. 9 activities, 2 booked, 1 in checkout, 6 planned.", "Your Kyoto wedding", btn("Trip Card","outline"), "live"),
        dline("Oct 3", "in 4 days", "Ceremony at Shimogamo Shrine, 15:00 Asia/Tokyo. 18 of 24 guests have answered.", "Your Kyoto wedding", btn("Guest list","outline"), "live", mono("event date · no RSVP deadline exists, so none is shown", None, "9.5px")),
        dline("Oct 14", "in 15 days", "Your anniversary. A draft plan from Kyoto arrives on Sep 30.", "Occasion", btn("Edit occasion","outline"), "neutral", pending("hidden until a Plus draft has fired")),
        dline("Nov 14", "in 46 days", "Lisbon long weekend begins. 4 items planned, nothing booked, no expert yet.", "Lisbon long weekend", btn("Open slip","outline"), "neutral"),
    ])
