WAVES = {0:"Wave 0 · ratify", 1:"Wave 1 · no ruling beyond record, no schema", 2:"Wave 2 · ruling-dependent, no schema", 3:"Wave 3 · schema and the large surface"}

def build_sequence_board():
    cols = []
    for w in (0,1,2,3):
        cards = []
        for (wave,lid,title,needs,schema,blocked,scope,files,guard) in LANES:
            if wave != w: continue
            chips = ""
            chips += pending(needs) if needs not in ("none",) else fixchip("no ruling")
            chips += (pending("migration") if schema == "migration" else fixchip("no schema"))
            cards.append(f'<div style="display: flex; flex-direction: column; gap: 6px; padding: 12px; border: 1px solid {T["border"]}; border-radius: 12px; background: {T["card"]};"><div style="display: flex; align-items: center; justify-content: space-between; gap: 6px;">{mono(lid, T["tealink"], "10px")}<div style="display: flex; gap: 4px;">{chips}</div></div><span style="font-family: {FR}; font-size: 14px; font-weight: 600; color: {T["navy"]};">{title}</span><span style="font-size: 11.5px; line-height: 1.45; color: {T["ink"]};">{scope}</span><span style="font-family: {MO}; font-size: 9.5px; color: {T["muted"]};">blocked by: {blocked}</span></div>')
        cols.append(f'<div style="flex: 1; display: flex; flex-direction: column; gap: 10px;"><div style="display: flex; flex-direction: column; gap: 2px; padding-bottom: 6px; border-bottom: 2px solid {T["navy"]};">{eyebrow(WAVES[w].split(" · ")[0], T["navy"])}<span style="font-size: 12px; color: {T["muted"]};">{WAVES[w].split(" · ")[1]}</span></div>' + "".join(cards) + '</div>')
    rules = card(f'{eyebrow("Every lane, per docs/OPERATING_PROCEDURE.md §3")}<span style="font-size: 12px; line-height: 1.5;">Branch task-&lt;slug&gt; off origin/main in its own worktree · one docs/DECISIONS.md row keyed YYYY-MM-DD-&lt;slug&gt; · every new test wired into build.yml · a new Playwright spec carries a spec-green line · CLAUDE.md delta only when a ruling is executed or amended · landed serially, one PR at a time · publish only through the preflight.</span>', "12px 14px")
    body = (f'<div style="display: flex; flex-direction: column; gap: 18px; padding: 32px 40px;"><div style="display: flex; align-items: flex-end; justify-content: space-between;"><div style="display: flex; flex-direction: column; gap: 6px;">{eyebrow("Build sequence")}<h1 style="margin: 0; font-family: {FR}; font-size: 28px; font-weight: 600; color: {T["navy"]};">Eighteen lanes in four waves</h1><span style="font-size: 13.5px; color: {T["muted"]};">A wave is a sequence, not a batch. Wave 1 can start before any ruling. Wave 2 waits on its ruling and on the lane it is blocked by. Wave 3 is the schema and the one lane that needs its own brief.</span></div>{rules}</div>'
            f'<div style="display: flex; gap: 16px; align-items: flex-start;">' + "".join(cols) + '</div></div>')
    return HEAD + f'<div style="width: 1880px; background: {T["ground"]}; display: flex; flex-direction: column;">' + body + '</div>' + FOOT

pathlib.Path("BuildSequence.dc.html").write_text(build_sequence_board()); print("BuildSequence", len(open("BuildSequence.dc.html").read()))

