head = f'<div style="display: grid; grid-template-columns: 150px 1fr 190px; padding: 10px 16px; background: #F6F5F1; font-family: {MO}; font-size: 10px; text-transform: uppercase; letter-spacing: 0.1em; color: #6A7480;"><span>Lane</span><span>Scope · files</span><span>Blocked by · guard</span></div>'
sec10 = (f'<div style="display: flex; flex-direction: column; gap: 12px;">{h2("10 · Build sequence: eighteen lanes in four waves")}'
         f'<p style="font-size: 14.5px; line-height: 1.6;">A wave is a sequence, not a batch: each lane lands serially, one PR at a time, and appends its own ledger row. <strong>Wave 0</strong> ratifies and preserves. <strong>Wave 1</strong> needs no ruling beyond the record and no schema, so it can start now. <strong>Wave 2</strong> waits on its ruling and on the lane it is blocked by. <strong>Wave 3</strong> is the one migration and the one lane large enough to need its own brief before it is built. Two things are deliberately not lanes: the push channel for the phone, which is a product decision nobody has taken, and the checkout page&#39;s move onto the plan projection, which is a gate inside L7 rather than a lane of its own until the audit says how far it got.</p>'
         f'<div style="border: 1px solid #E7E4DD; border-radius: 12px; background: #FFFFFF; overflow: hidden;">{head}{rows}</div>'
         f'<p style="font-size: 14.5px; line-height: 1.6;"><strong>Order inside a wave.</strong> Wave 1: L1 first, because every later screen lane assumes the shell; then L2, L3, L4, L5 in any order. Wave 2: L6 and L10 first, since the doors and Home are what a traveler meets; L7 only after its audit; L9 before L16 can mount its tab; L12, L13, L14 whenever a builder is free. Wave 3: L15 before L16; L17 waits on Decision 44 phase 0 and is listed so the dependency is visible, not so it is started.</p></div>')
anchor = '<div style="display: flex; flex-direction: column; gap: 6px; padding-top: 18px; border-top: 1px solid #E7E4DD;'
assert anchor in t
if "10 · Build sequence" not in t: t = t.replace(anchor, sec10 + '\n\n  ' + anchor, 1)
